    "id": "JAH-NMP2-000001",
    "name": "João",
    "kind": "first-name",
    "meaning": "João is a masculine given name in Portuguese. Meaning: God is gracious. The Portuguese form of John."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
